public class ContactTriggerHandler {

    public void beforeInsert(List<Contact> newContacts) {
        processBefore(newContacts, true);
    }

    public void beforeUpdate(List<Contact> newContacts) {
        processBefore(newContacts, false);
    }

    private void processBefore(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            Account a = accountMap.get(c.AccountId);
            if (a != null) {
                if (String.isBlank(c.MailingCountry)) {
                    c.MailingCountry = a.BillingCountry;
                }
                if (isInsert && String.isBlank(c.LeadSource)) {
                    c.LeadSource = a.AccountSource;
                }
            }
        }
    }

    public void afterInsert(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        Map<Id, Contact> accountToFirstContact = new Map<Id, Contact>();
        for (Contact c : newContacts) {
            if (c.AccountId != null
                    && String.isNotBlank(c.Phone)
                    && accountMap.containsKey(c.AccountId)) {
                Account a = accountMap.get(c.AccountId);
                if (String.isBlank(a.Phone)
                        && !accountToFirstContact.containsKey(c.AccountId)) {
                    accountToFirstContact.put(c.AccountId, c);
                }
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Contact c : accountToFirstContact.values()) {
            accountsToUpdate.add(new Account(Id = c.AccountId, Phone = c.Phone));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
