public class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {

        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200');
        }

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty');
        }

        if (String.isBlank(objectApiName)) {
            throw new SearchException('objectApiName must not be blank');
        }

        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        Schema.SObjectType objType = null;
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                objType = globalDescribe.get(key);
                break;
            }
        }
        if (objType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDescribe = objType.getDescribe();

        if (!objDescribe.isAccessible()) {
            throw new SearchException('User cannot read object: ' + objectApiName);
        }

        Map<String, Schema.DescribeFieldResult> fieldMap = new Map<String, Schema.DescribeFieldResult>();
        for (String fieldName : objDescribe.fields.getMap().keySet()) {
            Schema.SObjectField fieldToken = objDescribe.fields.getMap().get(fieldName);
            Schema.DescribeFieldResult dfr = fieldToken.getDescribe();
            fieldMap.put(dfr.getName().toLowerCase(), dfr);
        }

        List<String> selectFields = new List<String>{'Id'};
        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name must not be blank');
            }
            Schema.DescribeFieldResult dfr = fieldMap.get(f.toLowerCase());
            if (dfr == null) {
                throw new SearchException('Field does not exist on object: ' + f);
            }
            if (!dfr.isAccessible()) {
                throw new SearchException('User cannot read field: ' + f);
            }
            if (!dfr.getName().equalsIgnoreCase('Id')) {
                selectFields.add(dfr.getName());
            }
        }

        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult orderDfr = fieldMap.get(orderByField.toLowerCase());
            if (orderDfr == null) {
                throw new SearchException('Order by field does not exist: ' + orderByField);
            }
            if (!orderDfr.isAccessible()) {
                throw new SearchException('User cannot read order by field: ' + orderByField);
            }
            if (!orderDfr.isSortable()) {
                throw new SearchException('Order by field cannot be sorted: ' + orderByField);
            }
        }

        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                if (String.isBlank(key)) {
                    throw new SearchException('Filter key must not be blank');
                }
                Schema.DescribeFieldResult filterDfr = fieldMap.get(key.toLowerCase());
                if (filterDfr == null) {
                    throw new SearchException('Filter field does not exist: ' + key);
                }
                if (!filterDfr.isAccessible()) {
                    throw new SearchException('User cannot read filter field: ' + key);
                }
                if (!filterDfr.isFilterable()) {
                    throw new SearchException('Filter field cannot be filtered: ' + key);
                }
            }
        }

        String query = 'SELECT ' + String.join(selectFields, ', ') + ' FROM ' + objDescribe.getName();

        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            for (String key : filters.keySet()) {
                Object value = filters.get(key);
                Schema.DescribeFieldResult dfr = fieldMap.get(key.toLowerCase());
                String safeValue = formatValue(value, dfr);
                conditions.add(dfr.getName() + ' = ' + safeValue);
            }
            query += ' WHERE ' + String.join(conditions, ' AND ');
        }

        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult orderDfr = fieldMap.get(orderByField.toLowerCase());
            query += ' ORDER BY ' + orderDfr.getName() + ' ASC';
        }

        query += ' LIMIT ' + String.valueOf(maxRows);

        try {
            return Database.query(query);
        } catch (Exception e) {
            throw new SearchException('Search query failed: ' + e.getMessage());
        }
    }

    private static String formatValue(Object value, Schema.DescribeFieldResult dfr) {
        if (value == null) {
            return 'NULL';
        }

        if (value instanceof Id) {
            return '\'' + String.valueOf((Id) value).replace('\'', '\'\'') + '\'';
        } else if (value instanceof String) {
            return '\'' + ((String) value).replace('\'', '\'\'') + '\'';
        } else if (value instanceof Boolean) {
            return String.valueOf((Boolean) value);
        } else if (value instanceof Date) {
            return 'DATE ' + String.valueOf((Date) value);
        } else if (value instanceof DateTime) {
            return 'TIMESTAMP ' + String.valueOf((DateTime) value);
        } else if (value instanceof Decimal) {
            return String.valueOf((Decimal) value);
        } else if (value instanceof Integer) {
            return String.valueOf((Integer) value);
        } else {
            return '\'' + String.valueOf(value).replace('\'', '\'\'') + '\'';
        }
    }
}
