public class ShipmentEventPublisher {

    public class Shipment {
        public String orderNumber;
        public String trackingNumber;
        public String carrier;

        public Shipment(String orderNumber, String trackingNumber, String carrier) {
            this.orderNumber = orderNumber;
            this.trackingNumber = trackingNumber;
            this.carrier = carrier;
        }
    }

    public static Integer publishShipments(List<ShipmentEventPublisher.Shipment> shipments) {
        if (shipments == null || shipments.size() == 0) {
            return 0;
        }

        List<FB_Shipment_Event__e> platformEvents = new List<FB_Shipment_Event__e>();
        for (Shipment shipment : shipments) {
            if (shipment.orderNumber != null && shipment.orderNumber.trim().length() > 0) {
                FB_Shipment_Event__e evt = new FB_Shipment_Event__e();
                evt.Order_Number__c = shipment.orderNumber;
                evt.Tracking_Number__c = shipment.trackingNumber;
                evt.Carrier__c = shipment.carrier;
                platformEvents.add(evt);
            }
        }

        if (platformEvents.size() == 0) {
            return 0;
        }

        EventBus.publish(platformEvents);
        return platformEvents.size();
    }
}
