    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach ErpSyncFinalizer as transaction finalizer before doing any work
        context.registerFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        // Set Description to 'Synced to ERP' on all accounts
        List<Account> accounts = [SELECT Id FROM Account WHERE Id IN :accountIds];
        for (Account a : accounts) {
            a.Description = 'Synced to ERP';
        }

        // Save all-or-nothing; if any account cannot be saved the job fails (no try-catch)
        update accounts;
    }
}
