public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        setWithUserMode(true);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Schema.FieldSet creditReviewFieldSet =
            Account.SObjectType.getDescribe().fieldSets.getMap().get('Credit_Review');

        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember fsm : creditReviewFieldSet.getFields()) {
                fields.add(
                    Account.SObjectType.getDescribe().fields.getMap().get(fsm.getFieldPath())
                );
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fieldNames.add(String.valueOf(field));
        }

        ContactsSelector contactSelector = new ContactsSelector();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField field : contactSelector.getSObjectFieldList()) {
            contactFieldNames.add(String.valueOf(field));
        }
        fieldNames.add(
            '(SELECT ' + String.join(contactFieldNames, ', ') + ' FROM Contacts)'
        );

        String query =
            'SELECT ' +
            String.join(fieldNames, ', ') +
            ' FROM Account WHERE Id IN :accountIds WITH USER_MODE';

        return (List<Account>) Database.query(query);
    }
