public without sharing class LineItemDiscountHandler {

    /**
     * Sets a null Discount on each incoming line to its product's standard
     * discount. Lines that already have a Discount (including 0) are left
     * untouched.
     *
     * To stay within SOQL governor limits with up to 200 lines per quote,
     * all product lookups are collapsed into a single bulk SOQL query.
     * Discount logic itself is never duplicated — it is delegated to
     * PricingRules.standardDiscountForFamily, which PricingRules already
     * owns and maintains.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        if (lines == null || lines.isEmpty()) {
            return;
        }

        // Collect the unique product IDs that need a standard discount.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && String.isNotBlank(line.Product2Id)) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // One bulk SOQL instead of N individual queries inside PricingRules.
        Map<Id, Product2> productsById = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]
        );

        // Apply the standard discount to every line that still has null Discount.
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && String.isNotBlank(line.Product2Id)) {
                Product2 product = productsById.get(line.Product2Id);
                if (product != null) {
                    line.Discount = PricingRules.standardDiscountForFamily(product.Family);
                }
            }
        }
    }
}
