import { LightningElement, api, wire, track } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    _recordId;

    @api
    get recordId() {
        return this._recordId;
    }
    set recordId(value) {
        this._recordId = value;
    }

    @track record;
    @track error;

    @wire(getRecord, { recordId: '$_recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasData() {
        return !!this.record;
    }

    get hasError() {
        return !!this.error;
    }

    get accountName() {
        return this.record?.fields?.Name?.value ?? '';
    }

    get industry() {
        return this.record?.fields?.Industry?.value;
    }

    get annualRevenue() {
        return this.record?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        return this.record?.fields?.Owner?.fields?.Name?.value ?? '';
    }

    get errorMsg() {
        return this.error?.body?.message ?? '';
    }
}
