        this.loadOpportunities();
    }

    loadOpportunities() {
        this.loading = true;
        this.error = null;
        this.opportunities = null;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result;
                this.loading = false;
            })
            .catch((error) => {
                this.error = error;
                this.loading = false;
            });
    }

    handleRetry() {
        this.loadOpportunities();
    }
}
