import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines;
    showError = false;

    handleAction(event) {
        const action = event.target.dataset.action;
        const editors = this.template.querySelectorAll('c-line-item-editor');
        if (action === 'reset') {
            editors.forEach((editor) => editor.reset());
            this.showError = false;
        } else if (action === 'submit') {
            let allValid = true;
            const values = [];
            editors.forEach((editor) => {
                const valid = editor.validate();
                if (!valid) {
                    allValid = false;
                }
                values.push(editor.getValue());
            });
            if (allValid) {
                this.showError = false;
                this.dispatchEvent(
                    new CustomEvent('submit', { detail: { lines: values } })
                );
            } else {
                this.showError = true;
            }
        }
    }
}
