public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        /* Stage one NPSP Data Import record per gift with the staging
         * fields the org's NPSP Data Import engine matches on. */
        List<npsp__DataImport__c> stagedRecords = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c staged = new npsp__DataImport__c();
            staged.npsp__Contact1_Firstname__c      = gift.firstName;
            staged.npsp__Contact1_Lastname__c       = gift.lastName;
            staged.npsp__Contact1_Personal_Email__c = gift.email;
            staged.npsp__Donation_Amount__c         = gift.amount;
            staged.npsp__Donation_Date__c           = gift.giftDate;
            staged.npsp__Donation_Donor__c          = 'Contact1';
            stagedRecords.add(staged);
        }

        /* Insert the staged records. NPSP's automation (trigger/flow)
         * processes them synchronously within this transaction and
         * writes results back to the staging records. */
        insert stagedRecords;

        /* Collect explicit Ids for bulk-safe SOQL (avoids issues with
         * binding a large sObject list to an IN clause). */
        List<Id> stagedIds = new List<Id>();
        for (npsp__DataImport__c s : stagedRecords) {
            stagedIds.add(s.Id);
        }

        /* Bulk-read every processed staged record in a single SOQL. */
        Map<Id, ImportResult> resultByStagedId = new Map<Id, ImportResult>();

        for (npsp__DataImport__c rec : [
            SELECT Id
                 , npsp__Status__c
                 , npsp__Contact1Imported__c
                 , npsp__DonationImported__c
                 , npsp__FailureInformation__c
            FROM   npsp__DataImport__c
            WHERE  Id IN :stagedIds
        ]) {
            ImportResult r = new ImportResult();

            if (rec.npsp__Status__c == 'Imported') {
                r.success        = true;
                r.contactId      = rec.npsp__Contact1Imported__c;
                r.opportunityId  = rec.npsp__DonationImported__c;
                r.errorMessage   = null;
            } else {
                r.success       = false;
                r.contactId     = null;
                r.opportunityId = null;
                String failInfo = rec.npsp__FailureInformation__c;
                r.errorMessage  = (failInfo != null && !failInfo.isEmpty())
                    ? failInfo
                    : 'NPSP Data Import failed for this record';
            }

            resultByStagedId.put(rec.Id, r);
        }

        /* Assemble results in the original input order. */
        for (Id id : stagedIds) {
            ImportResult r = resultByStagedId.get(id);

            if (r == null) {
                r = new ImportResult();
                r.success       = false;
                r.contactId     = null;
                r.opportunityId = null;
                r.errorMessage  = 'NPSP Data Import record was not processed';
            }

            results.add(r);
        }

        return results;
    }
}
