public class HouseholdService {

    public class IllegalArgumentException extends Exception {}

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members cannot be null or empty');
        }

        // Resolve the Household Account record type Id dynamically (no hard-coded IDs)
        Id householdRecordTypeId = Account.SObjectType.getDescribe()
            .getRecordTypeInfosByDeveloperName()
            .get('HH_Account')
            .getRecordTypeId();

        // Insert the contacts first so they have Ids for linking
        insert members;

        // Create the single NPSP household account.
        // Use a provisional Name derived from the primary contact so the required
        // Name field is satisfied; NPSP naming automation finalises the household
        // name and greetings.
        String householdName = members[0].Name;
        if (String.isBlank(householdName)) {
            householdName = members[0].LastName;
        }
        if (String.isBlank(householdName)) {
            householdName = 'Household Account';
        }

        Account household = new Account();
        household.Name = householdName;
        household.RecordTypeId = householdRecordTypeId;
        household.npe01__One2OneContact__c = members[0].Id;
        insert household;

        // Associate every member to this household
        for (Contact c : members) {
            c.AccountId = household.Id;
        }
        update members;

        return household.Id;
    }
}
