public class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {

        // --- Guard: number of payments ---
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1.');
        }

        // --- Fetch the opportunity (also verifies it exists) ---
        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Cannot schedule installments for a closed opportunity.');
        }

        // --- Fetch all existing payments for this opportunity ---
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Opportunity__c,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c,
                   npe01__Payment_Method__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // --- Collect a payment method from existing payments (for the new ones) ---
        String paymentMethod = null;

        // --- Calculate outstanding amount (Amount minus paid & written‑off payments) ---
        Decimal paidAndWrittenOffAmount = Decimal.valueOf(0);
        for (npe01__OppPayment__c p : existingPayments) {
            if (p.npe01__Paid__c || p.npe01__Written_Off__c) {
                if (p.npe01__Payment_Amount__c != null) {
                    paidAndWrittenOffAmount += p.npe01__Payment_Amount__c;
                }
                if (paymentMethod == null && p.npe01__Payment_Method__c != null) {
                    paymentMethod = p.npe01__Payment_Method__c;
                }
            } else if (paymentMethod == null && p.npe01__Payment_Method__c != null) {
                paymentMethod = p.npe01__Payment_Method__c;
            }
        }

        Decimal opportunityAmount = opp.Amount != null ? opp.Amount : Decimal.valueOf(0);
        Decimal outstandingAmount = opportunityAmount - paidAndWrittenOffAmount;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero.');
        }

        // --- Delete unpaid, not written‑off payments ---
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : existingPayments) {
            if (!p.npe01__Paid__c && !p.npe01__Written_Off__c) {
                toDelete.add(p);
            }
        }
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }

        // --- Build new installment payments ---
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        Decimal baseAmount = outstandingAmount.divide(numberOfPayments, 2, RoundingMode.DOWN);
        Decimal totalScheduled = baseAmount * numberOfPayments;
        Decimal lastPaymentAmount = outstandingAmount - totalScheduled;

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c();
            payment.npe01__Opportunity__c    = opportunityId;
            payment.npe01__Payment_Amount__c = (i == numberOfPayments - 1) ? lastPaymentAmount : baseAmount;
            payment.npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i);
            payment.npe01__Payment_Date__c   = firstPaymentDate.addMonths(i);
