public class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    public void afterInsert(List<SObject> triggerNew) {
        List<Account> qualifyingAccounts = new List<Account>();
        for (SObject record : triggerNew) {
            Account acc = (Account) record;
            if (acc.Type == 'Customer - Direct' || acc.Type == 'Customer - Channel') {
                qualifyingAccounts.add(acc);
            }
        }

        if (qualifyingAccounts.isEmpty()) {
            return;
        }

        List<Task> tasks = new List<Task>();
        for (Account acc : qualifyingAccounts) {
            tasks.add(new Task(
                Subject     = 'Onboard new customer',
                WhatId      = acc.Id,
                OwnerId     = acc.OwnerId,
                ActivityDate = Date.today().addDays(7),
                Status      = 'Not Started',
                Priority    = 'Normal'
            ));
        }

        insert tasks;
    }
}
